import{_t as e,it as t,n,rt as r}from"./chunks/framework.BzA9dy5I.js";var i=JSON.parse(`{"title":"Publicar la documentación","description":"","frontmatter":{},"headers":[],"relativePath":"despliegue.md","filePath":"despliegue.md"}`),a={name:`despliegue.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="publicar-la-documentacion" tabindex="-1">Publicar la documentación <a class="header-anchor" href="#publicar-la-documentacion" aria-label="Permalink to “Publicar la documentación”">​</a></h1><p>Este sitio se publica en <strong>GitHub Pages</strong> desde el repositorio. El despliegue incluye únicamente la documentación generada.</p><h2 id="publicacion-inicial" tabindex="-1">Publicación inicial <a class="header-anchor" href="#publicacion-inicial" aria-label="Permalink to “Publicación inicial”">​</a></h2><p>La primera publicación usa la rama <code>gh-pages</code> con el sitio estático generado. La integración del código fuente y el workflow en <code>main</code> está en el <a href="https://github.com/0vas/hiperion/pull/6" target="_blank" rel="noreferrer">PR #6</a>, sujeta a las revisiones y controles del repositorio. Hasta que se integre, las actualizaciones del sitio se publican en esa rama.</p><h2 id="publicacion-automatica-tras-integrar-el-workflow" tabindex="-1">Publicación automática tras integrar el workflow <a class="header-anchor" href="#publicacion-automatica-tras-integrar-el-workflow" aria-label="Permalink to “Publicación automática tras integrar el workflow”">​</a></h2><p>Al integrar el workflow en <code>main</code>, cambia la fuente de Pages a <strong>GitHub Actions</strong> y ejecútalo desde Actions.</p><p>El workflow <code>.github/workflows/pages.yml</code> construye el sitio y verifica navegación, búsqueda y accesibilidad. Los pull requests validan cambios; una vez activada esa fuente, los cambios de documentación integrados en <code>main</code> publican el resultado automáticamente.</p><p>El artefacto sale de <code>docs/site/.vitepress/dist</code>. No incluye datos locales, credenciales ni el servidor de Hyperion.</p><h2 id="configuracion-del-repositorio" tabindex="-1">Configuración del repositorio <a class="header-anchor" href="#configuracion-del-repositorio" aria-label="Permalink to “Configuración del repositorio”">​</a></h2><p>En <strong>Settings → Pages → Build and deployment</strong>, usa <strong>Deploy from a branch → gh-pages → / (root)</strong> para la publicación inicial, o <strong>GitHub Actions</strong> para el workflow. El job de despliegue usa el entorno <code>github-pages</code> y permisos <code>pages: write</code> e <code>id-token: write</code>.</p><p>La URL de este repositorio es <a href="https://0vas.github.io/hiperion/" target="_blank" rel="noreferrer">0vas.github.io/hiperion</a>. El valor <code>base: &#39;/hiperion/&#39;</code> permite cargar enlaces y recursos desde esa ruta. Si publicas un fork con otro nombre, cambia <code>base</code>, el favicon y las expectativas de las pruebas.</p><h2 id="verificar-antes-de-publicar" tabindex="-1">Verificar antes de publicar <a class="header-anchor" href="#verificar-antes-de-publicar" aria-label="Permalink to “Verificar antes de publicar”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/site</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/site</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chromium</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/site</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>Puedes abrir el resultado con <code>npm --prefix docs/site run preview</code> y visitar <code>http://127.0.0.1:4175/hiperion/</code>.</p><p>Con GitHub Actions activado, si falla el despliegue, revisa el workflow <strong>Documentation Pages</strong> en Actions. Para volver a publicar, usa <strong>Run workflow</strong> sobre <code>main</code>. Si el contenido es incorrecto, revierte el cambio en el repositorio y deja que el workflow vuelva a publicar.</p><p>Referencias: <a href="https://vitepress.dev/guide/deploy" target="_blank" rel="noreferrer">despliegue de VitePress</a> y <a href="https://docs.github.com/en/pages/getting-started-with-github-pages/using-custom-workflows-with-github-pages" target="_blank" rel="noreferrer">workflows de GitHub Pages</a>.</p>`,16)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};